{ "version": 1, "title": "Sequential vs Concurrent", "page": { "width": 1008.0, "height": 612.0, "margin": 36.0, "background": "#ffffff" }, "elements": [ { "type": "label", "id": "title", "x": 48.0, "y": 32.0, "text": "Sequential vs Concurrent", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 30.0, "font_weight": 700, "italic": null, "text_color": null, "align": null, "padding": null } }, { "type": "label", "id": "sub", "x": 48.0, "y": 70.0, "text": "Awaiting in a loop is a queue. Promise.all is a starting gun for tasks that do not depend on each other.", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 15.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "shape", "id": "h1", "kind": "rect", "x": 48.0, "y": 110.0, "w": 620.0, "h": 34.0, "text": "await one at a time: 3 seconds", "style": { "fill": "#fbe3e3", "stroke": "#c93434", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 16.0, "font_weight": 700, "italic": null, "text_color": "#7a1d1d", "align": null, "padding": null } }, { "type": "shape", "id": "s1", "kind": "rect", "x": 48.0, "y": 154.0, "w": 200.0, "h": 40.0, "text": "fetch A (1s)", "style": { "fill": "#fbe3e3", "stroke": "#c93434", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#7a1d1d", "align": null, "padding": null } }, { "type": "shape", "id": "s2", "kind": "rect", "x": 258.0, "y": 154.0, "w": 200.0, "h": 40.0, "text": "fetch B (1s)", "style": { "fill": "#fbe3e3", "stroke": "#c93434", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#7a1d1d", "align": null, "padding": null } }, { "type": "shape", "id": "s3", "kind": "rect", "x": 468.0, "y": 154.0, "w": 200.0, "h": 40.0, "text": "fetch C (1s)", "style": { "fill": "#fbe3e3", "stroke": "#c93434", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#7a1d1d", "align": null, "padding": null } }, { "type": "shape", "id": "c1code", "kind": "rect", "x": 48.0, "y": 206.0, "w": 620.0, "h": 68.0, "text": "for (const url of urls) {
 results.push(await fetch(url));
}", "style": { "fill": "#ffffff", "stroke": "#c93434", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": "mono", "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "h2", "kind": "rect", "x": 48.0, "y": 300.0, "w": 620.0, "h": 34.0, "text": "start them all, then await: 1 second", "style": { "fill": "#d9f2e9", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 16.0, "font_weight": 700, "italic": null, "text_color": "#0a4d36", "align": null, "padding": null } }, { "type": "shape", "id": "p1", "kind": "rect", "x": 48.0, "y": 344.0, "w": 200.0, "h": 32.0, "text": "fetch A (1s)", "style": { "fill": "#d9f2e9", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#0a4d36", "align": null, "padding": null } }, { "type": "shape", "id": "p2", "kind": "rect", "x": 48.0, "y": 380.0, "w": 200.0, "h": 32.0, "text": "fetch B (1s)", "style": { "fill": "#d9f2e9", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#0a4d36", "align": null, "padding": null } }, { "type": "shape", "id": "p3", "kind": "rect", "x": 48.0, "y": 416.0, "w": 200.0, "h": 32.0, "text": "fetch C (1s)", "style": { "fill": "#d9f2e9", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#0a4d36", "align": null, "padding": null } }, { "type": "shape", "id": "c2code", "kind": "rect", "x": 268.0, "y": 344.0, "w": 400.0, "h": 104.0, "text": "const results = await Promise.all(
 urls.map((url) => fetch(url))
);", "style": { "fill": "#ffffff", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": "sans", "font_size": 14.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "hC", "kind": "rect", "x": 700.0, "y": 110.0, "w": 260.0, "h": 34.0, "text": "Which combinator?", "style": { "fill": "#e6e4f6", "stroke": "#4a3aa7", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 16.0, "font_weight": 700, "italic": null, "text_color": "#2a2160", "align": null, "padding": null } }, { "type": "shape", "id": "cb1", "kind": "rect", "x": 700.0, "y": 154.0, "w": 260.0, "h": 76.0, "text": "Promise.all
All must succeed. Rejects as
soon as any one rejects.", "style": { "fill": "#ffffff", "stroke": "#0f8f63", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "cb2", "kind": "rect", "x": 700.0, "y": 238.0, "w": 260.0, "h": 76.0, "text": "Promise.allSettled
Never rejects. Gives you a
status for every one.", "style": { "fill": "#ffffff", "stroke": "#2a78d6", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "cb3", "kind": "rect", "x": 700.0, "y": 322.0, "w": 260.0, "h": 76.0, "text": "Promise.race
First to SETTLE wins, even if
that one rejected. Timeouts.", "style": { "fill": "#ffffff", "stroke": "#d9541f", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "cb4", "kind": "rect", "x": 700.0, "y": 406.0, "w": 260.0, "h": 76.0, "text": "Promise.any
First to SUCCEED wins.
Rejects only if all reject.", "style": { "fill": "#ffffff", "stroke": "#c74d7c", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 13.0, "font_weight": null, "italic": null, "text_color": null, "align": "left", "padding": null } }, { "type": "shape", "id": "warn", "kind": "note", "x": 48.0, "y": 506.0, "w": 912.0, "h": 66.0, "text": "Only fan out when the tasks are INDEPENDENT. If step B needs step A's result, awaiting in sequence is not a bug; it is
the requirement. And Promise.all does not create threads: the waiting overlaps, the JavaScript still runs on one thread.", "style": { "fill": "#fbeecf", "stroke": "#b07d00", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 14.0, "font_weight": null, "italic": null, "text_color": "#5c4100", "align": "left", "padding": null } }, { "type": "label", "id": "t0", "x": 48.0, "y": 458.0, "text": "0s", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 12.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "label", "id": "t1", "x": 243.0, "y": 458.0, "text": "1s", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 12.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "label", "id": "t2", "x": 453.0, "y": 458.0, "text": "2s", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 12.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "label", "id": "t3", "x": 656.0, "y": 458.0, "text": "3s", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 12.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "label", "id": "tlab", "x": 320.0, "y": 476.0, "text": "elapsed time", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 12.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } } ], "next_id": {} }
